import numpy as np, itertools
L=open('opt5.xyz').read().split('\n'); n=int(L[0])
pos=np.array([[float(x) for x in l.split()[1:4]] for l in L[2:2+n]])
for p in [(7,0),(7,6),(7,27),(7,33),(7,8),(7,58)]:
    print(p, round(np.linalg.norm(pos[p[0]]-pos[p[1]]),2))
def ang(i,j,k):
    a=pos[i]-pos[j]; b=pos[k]-pos[j]
    return np.degrees(np.arccos(a.dot(b)/np.linalg.norm(a)/np.linalg.norm(b)))
for i,j in itertools.combinations([6,8,27,33],2): print(i,j,round(ang(i,7,j),1))
